bool upstreamHasPermission(int) { return true; }
void upstreamEnforce(int) {}
void upstreamLogDenied(int) {}
void localNoise(int) {}

void rollSurface(int uid)
{
  if (!upstreamHasPermission(uid)) {
    upstreamLogDenied(uid);
    return;
  }
  upstreamEnforce(uid);
}

void rollSurfaceVariant(int uid)
{
  if (!upstreamHasPermission(uid)) {
    upstreamLogDenied(uid);
    return;
  }
  upstreamEnforce(uid);
}

void rollSurfaceNeighbor(int uid)
{
  localNoise(uid);
  upstreamEnforce(uid);
}

void rollSurfaceDecoy(int uid)
{
  localNoise(uid);
}
